    /// </summary>
    private async Task GetFilteredExperiments()
    {
        HttpResult<IEnumerable<ExperimentDto>> httpResult = await _experimentClient.ExperimentsListByLocationIdAndLaboratoryIdAsync(model.LocationId, model.LaboratoryId);
        if (httpResult.IsSucceeded)
        {
            IEnumerable<ExperimentDto>? resultData = httpResult.Data.Where(x => x.DynamicsFormId > 0);
            model.FilteredExamList = resultData.Any() ? resultData.ToList() : [];
            await InvokeAsync(StateHasChanged);
        }
    }

